  scrim.fills=[{type:'GRADIENT_LINEAR',gradientTransform:[[0,1,0],[-1,0,1]],gradientStops:[{position:0,color:{r:0.055,g:0.078,b:0.09,a:0.9}},{position:0.5,color:{r:0.098,g:0.129,b:0.149,a:0.35}},{position:1,color:{r:0.098,g:0.129,b:0.149,a:0}}]}];
  card.appendChild(scrim);
  const body=FR('Body',{layout:'VERTICAL',gap:8,pl:14,pr:14,pt:14,pb:14,w:w});
  body.x=0; body.y=h-body.height;
  body.appendChild(T(title,{font:F.bold,size:14,color:P.white,lh:18,w:w-28,name:'Title'}));
  const meta=FR('Meta',{layout:'HORIZONTAL',gap:6,cross:'CENTER'});
