function T(chars,o={}){const t=figma.createText();t.fontName=o.font||F.reg;t.fontSize=o.size||14;t.characters=chars;t.fills=S(o.color||P.text);if(o.lh)t.lineHeight={unit:'PIXELS',value:o.lh};if(o.ls)t.letterSpacing={unit:'PIXELS',value:o.ls};if(o.name)t.name=o.name;if(o.align)t.textAlignHorizontal=o.align;if(o.w){t.textAutoResize='HEIGHT';t.resize(o.w,10);}return t;}
function FR(name,o={}){const f=figma.createFrame();f.name=name;f.fills=o.fill?S(o.fill):[];if(o.r!==undefined)f.cornerRadius=o.r;if(o.layout){f.layoutMode=o.layout;f.itemSpacing=o.gap||0;f.paddingTop=o.pt||0;f.paddingBottom=o.pb||0;f.paddingLeft=o.pl||0;f.paddingRight=o.pr||0;f.primaryAxisAlignItems=o.main||'MIN';f.counterAxisAlignItems=o.cross||'MIN';f.primaryAxisSizingMode=o.pSize||'AUTO';f.counterAxisSizingMode=o.cSize||'AUTO';}if(o.w&&o.h)f.resize(o.w,o.h);if(o.clip!==undefined)f.clipsContent=o.clip;if(o.fx)f.effects=o.fx;if(o.stroke){f.strokes=S(o.stroke);f.strokeWeight=o.sw||1;f.strokeAlign='INSIDE';}return f;}
