async function txt(chars,style,size,color,lh,ls){
  const t=figma.createText();
  t.fontName={family:'Lato',style};
  t.characters=chars; t.fontSize=size;
  t.fills=[{type:'SOLID',color}];
  if(lh) t.lineHeight={unit:'PIXELS',value:lh};
  if(ls!==undefined) t.letterSpacing={unit:'PERCENT',value:ls};
  return t;
}
function recolor(n,color){
  if('fills' in n){ try{ const f=n.fills; if(Array.isArray(f)&&f.length&&f[0].type==='SOLID') n.fills=[{type:'SOLID',color}]; }catch(e){} }
  if('strokes' in n){ try{ const s=n.strokes; if(Array.isArray(s)&&s.length&&s[0].type==='SOLID') n.strokes=[{type:'SOLID',color}]; }catch(e){} }
  if('children' in n) n.children.forEach(c=>recolor(c,color));
}

