async function buildChip(name, iconId, text, fg, bg){
  const c = figma.createComponent();
  c.name=name;
  c.fills = bg?[{type:'SOLID',color:bg}]:[];
  c.cornerRadius=9;
  c.layoutMode='HORIZONTAL'; c.itemSpacing=3;
  c.paddingTop=4;c.paddingBottom=4;c.paddingLeft=7;c.paddingRight=7;
  c.counterAxisAlignItems='CENTER'; c.primaryAxisAlignItems='CENTER';
  c.primaryAxisSizingMode='AUTO'; c.counterAxisSizingMode='AUTO';
  lib.appendChild(c);
  const ic=(await G(iconId)).createInstance();
  c.appendChild(ic); ic.resize(10,10);
  const t=figma.createText();
  t.fontName={family:'Lato',style:'Bold'}; t.fontSize=10; t.characters=text;
  t.fills=[{type:'SOLID',color:fg}];
  c.appendChild(t);
  return c;
}
